insert into public.site_settings (id, site_title, meta_description, footer_note, show_assistant)
values (1, 'Alex Morgan — Creative Developer', 'Alex Morgan is a creative developer building playful, AI-powered digital experiences. Explore projects, skills and experience — or ask Momo, the portfolio cat.', 'Designed and built with care, curiosity and one very opinionated cat.', true)
