insert into public.profiles (id, name, designation, introduction, description, location, availability, profile_image_url, cta_primary_label, cta_primary_href, cta_secondary_label, cta_secondary_href, stats)
values (1, 'Alex Morgan', 'Creative Developer & AI Enthusiast', 'Building digital experiences that combine technology, creativity and a little bit of magic.', 'I design and engineer interfaces that feel alive — from AI-assisted tools to motion-rich product sites. Eight years of shipping for startups and studios taught me that the details people notice are rarely the ones in the spec.', 'Lisbon, Portugal · Remote', 'Open to freelance & full-time roles from January', '/placeholders/profile.svg', 'See my work', '#work', 'Get in touch', '#contact', '[{"value":"8+","label":"years building for the web"},{"value":"40","label":"products shipped"},{"value":"12","label":"AI features in production"},{"value":"3","label":"design awards"}]'::jsonb)
