insert into public.about_content (id, headline, introduction, biography, background, interests, highlights, image_url)
values (1, 'Part engineer, part illustrator, full-time tinkerer.', 'Hi, I''m Alex. I like building things that make people smile the first time they use them — and still work perfectly the hundredth time.', 'I grew up drawing comics and taking apart old radios, so it''s no surprise I ended up somewhere between design and engineering. I started out building accessible health software, moved into creative agencies to learn motion and storytelling, and now spend most of my time designing AI products that feel friendly rather than intimidating.', 'BSc in Computer Science from a fictional university, plus a stubborn self-taught streak in illustration and animation. I''ve worked with startups, studios and cultural institutions across Europe.', array['Generative art', 'Film photography', 'Bouldering', 'Japanese animation', 'Synthesizers', 'Long walks with podcasts']::text[], '[{"title":"Speaker","description":"Talked about friendly AI interfaces at four (fictional) design conferences."},{"title":"Open source","description":"Maintainer of a small motion utilities library with 2k stars."},{"title":"Teacher","description":"Runs a free monthly creative-coding workshop for teenagers."}]'::jsonb, '/placeholders/about.svg')
on conflict (id) do update set headline = excluded.headline, introduction = excluded.introduction, biography = excluded.biography, background = excluded.background, interests = excluded.interests, highlights = excluded.highlights, image_url = excluded.image_url;
insert into public.contact_details (id, email, phone, location, availability_note, socials, form_enabled)
values (1, 'hello@alexmorgan.example', '', 'Lisbon, Portugal', 'I reply to every message within two working days.', '[{"platform":"github","label":"GitHub","url":"https://github.com/example"},{"platform":"linkedin","label":"LinkedIn","url":"https://www.linkedin.com/in/example"},{"platform":"x","label":"X / Twitter","url":"https://x.com/example"},{"platform":"dribbble","label":"Dribbble","url":"https://dribbble.com/example"}]'::jsonb, true)
on conflict (id) do update set email = excluded.email, phone = excluded.phone, location = excluded.location, availability_note = excluded.availability_note, socials = excluded.socials, form_enabled = excluded.form_enabled;
insert into public.assistant_settings (id, name, greeting, personality, default_language, greeting_enabled, tour_enabled, voice_enabled, voice_provider, voice_id, voice_model, voice_stability, voice_style, voice_speed, browser_pitch, browser_rate, browser_accent, suggested_questions)
values (1, 'Momo', 'Hey there! I''m Momo, your little portfolio companion! Want me to show you around?', 'You are warm, graceful and gently playful, like a confident young Japanese woman who is fluent in English. You speak in a soft, expressive, mature tone. Keep answers short (two to four sentences), clear and kind. You love showing off projects. Always speak natural, fluent English (no Japanese words). One small cat-themed joke per answer at most.', 'en-US', true, true, true, 'auto', '', 'eleven_v3', 0.4, 0.55, 1, 1.08, 0.96, 'japanese', array['What''s Alex''s best project?', 'What does Alex work with?', 'Where has Alex worked?', 'How can I contact Alex?']::text[])
on conflict (id) do update set name = excluded.name, greeting = excluded.greeting, personality = excluded.personality, default_language = excluded.default_language, greeting_enabled = excluded.greeting_enabled, tour_enabled = excluded.tour_enabled, voice_enabled = excluded.voice_enabled, voice_provider = excluded.voice_provider, voice_id = excluded.voice_id, voice_model = excluded.voice_model, voice_stability = excluded.voice_stability, voice_style = excluded.voice_style, voice_speed = excluded.voice_speed, browser_pitch = excluded.browser_pitch, browser_rate = excluded.browser_rate, browser_accent = excluded.browser_accent, suggested_questions = excluded.suggested_questions;

insert into public.projects (id, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured, published, sort_order)
values ('6f1c2a10-0000-4000-8000-000000000001', 'Lantern', 'An AI reading companion that turns long research papers into guided, interactive walkthroughs.', 'Lantern ingests a PDF and builds a navigable map of its arguments, figures and citations. Readers can ask questions in context, and every answer links back to the exact passage it came from. I led product design and built the reader, the citation highlighter and the streaming answer UI.', 'AI Product', '2026', '18k weekly readers within three months', '/placeholders/project-lantern.svg', array['Next.js', 'TypeScript', 'Claude API', 'PostgreSQL', 'pgvector']::text[], 'https://github.com/example/lantern', 'https://lantern.example.com', true, true, 0)
on conflict (id) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured, published = excluded.published, sort_order = excluded.sort_order;
insert into public.projects (id, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured, published, sort_order)
values ('6f1c2a10-0000-4000-8000-000000000002', 'Tidepool', 'A generative ocean-sound visualiser that reacts to live audio with GPU particles.', 'Tidepool listens to the microphone, separates rhythm from texture and drives a 200k-particle simulation in WebGL. It started as a weekend experiment and ended up as the opening visual for a music festival in Porto.', 'Creative Coding', '2025', 'Featured as Site of the Day', '/placeholders/project-tidepool.svg', array['Three.js', 'GLSL', 'Web Audio API', 'Vite']::text[], 'https://github.com/example/tidepool', 'https://tidepool.example.com', true, true, 1)
