insert into public.projects (id, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured, published, sort_order)
values ('6f1c2a10-0000-4000-8000-000000000003', 'Fieldnote', 'A calm, offline-first journaling app with on-device mood insights.', 'Fieldnote keeps every entry on the device, syncs end-to-end encrypted, and uses a small on-device model to surface gentle weekly patterns. I built the React Native client and the encrypted sync protocol.', 'Mobile App', '2025', '4.8★ average across 2,000 reviews', '/placeholders/project-fieldnote.svg', array['React Native', 'Expo', 'SQLite', 'TensorFlow Lite']::text[], 'https://github.com/example/fieldnote', null, false, true, 2)
