insert into public.projects (id, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured, published, sort_order)
values ('6f1c2a10-0000-4000-8000-000000000004', 'Switchboard', 'A design-system dashboard that tracks component usage across thirty product repositories.', 'Switchboard scans repositories nightly, maps which components and tokens each team uses, and flags drift from the design system. It cut the time to plan a breaking change from weeks to an afternoon.', 'Developer Tool', '2024', 'Adopted by 30 product teams', '/placeholders/project-switchboard.svg', array['React', 'Node.js', 'GraphQL', 'D3.js']::text[], 'https://github.com/example/switchboard', 'https://switchboard.example.com', false, true, 3)
