values ('6f1c2a10-0000-4000-8000-000000000005', 'Sprout', 'A playful plant-care assistant that identifies plants from a photo and schedules reminders.', 'Sprout combines an image classifier with a friendly conversational layer. The fun part was the character design: the plant mascot changes expression depending on how thirsty your plants are.', 'AI Product', '2024', 'Top 10 in the Lifestyle category', '/placeholders/project-sprout.svg', array['Python', 'FastAPI', 'PyTorch', 'Svelte']::text[], 'https://github.com/example/sprout', 'https://sprout.example.com', false, true, 4)
