values ('6f1c2a10-0000-4000-8000-000000000006', 'Paper Planes', 'An interactive scroll story about the history of flight, built for a science museum.', 'A scroll-driven narrative with hand-drawn illustrations, folded-paper transitions and an accessibility-first reading mode. Built in close collaboration with the museum''s education team.', 'Interactive Story', '2023', 'Used by 60 schools for remote lessons', '/placeholders/project-paperplanes.svg', array['GSAP', 'SVG', 'Astro', 'Accessibility']::text[], null, 'https://paperplanes.example.com', false, true, 5)
